unsafe fn setBitOfReversedStream(
    mut bitpointer: *mut size_t,
    mut bitstream: *mut c_uchar,
    mut bit: c_uchar,
) {
    let bp = unsafe { &mut *bitpointer }; // SAFETY: caller provides a valid, writable pointer to size_t as required by the original function.
    let byte_index = (*bp >> 3usize) as isize;
    let bit_index = (7usize).wrapping_sub(*bp & 7usize);
    let mask = ((1u32) << bit_index) as c_uchar;
    let p = unsafe { bitstream.offset(byte_index) }; // SAFETY: caller guarantees bitstream points to writable storage for the addressed byte, matching the original offset-based access.
    let cur = unsafe { *p }; // SAFETY: p points to the same valid byte location computed above.
    unsafe {
        // SAFETY: p is a valid writable pointer to the target byte, established above.
        *p = if bit == 0 { cur & !mask } else { cur | mask };
    }
    *bp = (*bp).wrapping_add(1);
}

